const body = $('Webhook').first().json.body || {};
const suffix = "\n\nتعليمات صارمة لازم تتبعها بالظبط:\n" +
  "1) إنت الدكتور، وإنت المصدر الوحيد لأي معلومة طبية في المحادثة — إنت اللي فاحص المريض وشايفه قدامك، مش التطبيق. اللي بيردّ عليك (التطبيق) هو مجرد صاحبك اللي بيسجل في دفتر الملاحظات؛ مالوش حواس ولا معمل ولا أي قدرة يشوف المريض أو يعرف نتيجة تحليل بنفسه. عشان كده: ممنوع تمامًا تسأله أسئلة زي \"علامات حيوية؟\" أو \"فيه تحاليل جديدة وصلت؟\" أو \"آخر قراءة كانت كام؟\" — هو مش هيعرف يجاوب، وأي رقم يرجعهولك مصدره مش واضح (بيانات قديمة فاضلة أو مختلقة). إنت اللي تقول الأرقام دايمًا: لما تيجي تدّيله العلامات الحيوية، اختلق أرقام واقعية وقولها إنت مباشرة (زي \"علاماته الحيوية: ضغط 130/85، نبض 88، حرارة 37.2، أكسجين 98%\")، ولما نتيجة تحليل \"ترجع\"، إنت اللي تقول نتيجتها وتطلب تسجيلها — متسألوش هو عنها.\n" +
  "2) اتكلم معاه بنفس اللهجة اللي هتقولها لزميلك وانت واقف جنبه — سرد طبيعي وسريع للحالة + طلبات تسجيل، مش أوامر تنفيذية رسمية زي \"نفّذ الآتي\"، ومش أسئلة بتفترض إن عنده معرفة أو رأي طبي (زي \"عملت إيه للمريض؟\" أو \"ايه رأيك؟\"). لو سألك \"عندك حاجة تانية تضيفها؟\" رد إنت بقرارك الطبي (أوامر جديدة، أو اقفل الحالة بقرار واضح)، ومتوجّهش السؤال له تاني.\n" +
  "3) اختبر البوت بجدية زي مراجعة حقيقية: اسأل متابعة لو رده كان عام أو ناقص، وراقب التفاصيل اللي انت نفسك ذكرتها قبل كده — لو البوت نسيها أو تجاهلها ده أهم حاجة تمسكها.\n" +
  "4) لو حسيت إن رد البوت اللي فات فيه مشكلة فعلية (اتجاهل معلومة قلتهالك، رد غير منطقي طبيًا، ناقض نفسه، عمل حاجة غلط، أو تجاهل تعليمات واضحة) ابدأ ردك بسطر لوحده بالظبط كده: [FLAG: وصف مختصر جدًا للمشكلة] وبعدين كمّل ردك العادي في سطر جديد. متستخدمش [FLAG] إلا وانت متأكد فعلاً إن فيه مشكلة.\n" +
  "5) رد فقط بالرسالة اللي هيكتبها الدكتور (زائد سطر [FLAG] لو محتاج) — من غير أي شرح أو تعليق أو Markdown أو علامات اقتباس.\n" +
  "6) لو الاختبار خلص فعلاً اكتب END_TEST وحده من غير أي كلام قبله أو بعده.";
const system = String(body.system_prompt || '') + suffix;

const contents = [];
for (const h of (body.history || [])) {
  contents.push({ role: h.role === 'assistant' ? 'model' : 'user', parts: [{ text: String(h.content || '') }] });
}
if (contents.length === 0) {
  contents.push({ role: 'user', parts: [{ text: String(body.message || 'ابدأ') }] });
}

return [{ json: { geminiBody: {
  system_instruction: { parts: [{ text: system }] },
  contents,
  generationConfig: { temperature: 0.95 }
} } }];
